package lk.ac.sliit.ridelink.driver.infrastructure.documentation;
import io.swagger.v3.oas.models.*; import io.swagger.v3.oas.models.info.Info; import io.swagger.v3.oas.models.security.SecurityScheme; import org.springframework.context.annotation.*;
@Configuration public class OpenApiConfiguration {@Bean OpenAPI api(){return new OpenAPI().info(new Info().title("RideLink Driver and Vehicle Service API").version("v1").description("Driver operations, vehicles, availability and deterministic assignment eligibility")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT")));}}
